window.TEIQ_EMBED = {"fonts":{"Inter":"","Manrope":""},"images":{"assets/cover-2026.jpg":"data:image/jpeg;base64,","assets/back-cover.jpg":"data:image/jpeg;base64,","assets/logo-monogram.png":"data:image/png;base64,"},"reportCss":"/* TEIQue 360 report pages. Units are points: the Figma frames are 595 x 842, which is A4 in points,\n   so every Figma number can be used as-is. */\n@font-face { font-family: 'Inter'; src: url('../../fonts/Inter-Variable.ttf') format('truetype'); font-weight: 100 900; }\n@font-face { font-family: 'Manrope'; src: url('../../fonts/Manrope-Variable.ttf') format('truetype'); font-weight: 200 800; }\n\n@page { size: 595pt 842pt; margin: 0; }\n* { box-sizing: border-box; }\nhtml, body { margin: 0; padding: 0; }\nbody { font-family: Inter, 'Segoe UI', Arial, sans-serif; color: #000; -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n\n.page { --c: #42A2DA; width: 595pt; height: 842pt; position: relative; overflow: hidden; background: #fff; break-after: page; }\n.page:last-child { break-after: auto; }\n@media screen {\n  body { background: #E9EBEF; padding: 16pt 0; }\n  .page { margin: 0 auto 16pt; box-shadow: 0 2pt 14pt rgba(0, 0, 0, .18); }\n}\n\n/* running header and footer */\n.hdr { position: absolute; z-index: 3; top: 0; left: 0; right: 0; height: 62pt; background: #fff; box-shadow: 0 0 15.5pt rgba(0, 0, 0, .10);\n  display: flex; align-items: center; justify-content: space-between; padding: 0 40pt; }\n.hdr .prod { font: 500 18pt Inter, sans-serif; color: #42A2DA; }\n.hdr .prod i { font-style: normal; color: #E47C2D; }\n.hdr .logo { position: absolute; left: 50%; top: 10pt; height: 42pt; transform: translateX(-50%); }\n.hdr .who { font: 300 12pt/15pt Inter, sans-serif; text-align: right; max-width: 190pt; }\n.hdr .who div { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.ftr { position: absolute; z-index: 3; left: 0; right: 0; bottom: 0; height: 30pt; text-align: center; font: 300 11pt/14.5pt Inter, sans-serif; }\n.ftr .pg { font-weight: 100; }\n.ftr .pg b { font-weight: 300; color: var(--c); }\n.ftr .cr { font-size: 10pt; color: #B7B6B7; }\n\n/* sample watermark: sits behind the content, never over text cards or the footer */\n.wm { position: absolute; z-index: 0; inset: 70pt 0 40pt 0; display: grid; grid-template-columns: repeat(3, 1fr); align-content: space-around; pointer-events: none; }\n.wm span { font: 500 11pt/13pt Manrope, sans-serif; color: #000; opacity: .07; text-align: center; transform: rotate(-24deg); }\n\n.body { position: absolute; z-index: 1; top: 62pt; bottom: 28pt; left: 0; right: 0; padding: 26pt 40pt 6pt; display: flex; flex-direction: column; gap: 16pt; overflow: hidden; }\n.body > * { flex: none; }\n\nh1.title { font: 500 26pt/32pt Manrope, sans-serif; color: var(--c); margin: 0; }\n.eyebrow { font: 700 8.5pt/11pt Manrope, sans-serif; letter-spacing: .09em; text-transform: uppercase; color: #808080; margin-bottom: 2pt; }\np { font: 300 12pt/14.5pt Inter, sans-serif; text-align: justify; hyphens: auto; margin: 0; }\np + p { margin-top: 8pt; }\np.lead { font-weight: 500; color: var(--c); margin: -4pt 0 6pt; }\np.note { font-size: 11pt; line-height: 14.5pt; color: #555; text-align: left; }\nh4.sub { font: 500 14pt/17pt Inter, sans-serif; color: var(--c); margin: 0 0 10pt; }\n.card { background: #fff; border-radius: 15pt; padding: 15pt; box-shadow: 0 0 10pt rgba(0, 0, 0, .15); }\n.card ul { margin: 0; padding-left: 16pt; font: 300 12pt/14.5pt Inter, sans-serif; }\n.card li + li { margin-top: 6pt; }\n.cmp { font-weight: 500; }\n.needed { border: 1pt dashed #C9A227; background: #FFF9E5; border-radius: 8pt; padding: 5pt 9pt; font: 500 9pt/12pt Inter, sans-serif; color: #7A5B00; margin-bottom: 8pt; text-align: left; }\n.filler { color: #8A8F98; }\n\n.chart svg { display: block; width: 100%; max-width: none !important; height: auto; }\n.chart.center { align-self: center; }\n.row { display: flex; gap: 37pt; align-items: flex-start; }\n.row .txt { flex: 1; min-width: 0; }\n.row .gauge { width: 155pt; flex: none; margin-top: -6pt; }\n\n/* \"Added\" tag: marks what the 2010 report did not have. A small solid pill in brand blue, never part of\n   the layout flow inside a chart, so switching the tags off moves nothing. */\n.added { display: inline-flex; align-items: center; gap: 3.5pt; font: 700 7.5pt/1 Manrope, sans-serif; letter-spacing: .07em; text-transform: uppercase; white-space: nowrap;\n  color: #fff; background: #42A2DA; border-radius: 20pt; padding: 3.6pt 8pt 3.6pt 6pt; }\n.added::before { content: '+'; font-size: 10pt; font-weight: 700; line-height: .7; margin-top: -.6pt; }\nh1.title .added { vertical-align: middle; margin-left: 12pt; position: relative; top: -2pt; }\n.chart { position: relative; }\n.chart > .added { position: absolute; top: 0; right: 0; z-index: 2; }\n/* on a score wheel the tag starts at the wheel's top right corner and runs outwards, clear of the ring */\n.scores .wheel > .added { right: auto; left: calc(100% - 26pt); }\n\n/* cover and back cover */\n.page.full img.bg { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }\n/* cover, after the template in brief/cover-template-2026-11.pdf. Positions and sizes are the template's,\n   in points. The artwork image already holds the ribbon, the logo and the blue name bar. */\n.cover .cr, .cover .legal { position: absolute; left: 0; right: 0; text-align: center; font: 400 10.6pt/14.5pt Manrope, sans-serif; color: #6B7380; }\n.cover .cr { top: 8.8pt; }\n.cover .legal { top: 816.3pt; }\n.cover .ttl { position: absolute; left: 28.1pt; top: 217.4pt; font: 700 28.5pt/35.4pt Manrope, sans-serif; color: #2B9CD6; }\n.cover .ttl i { font-style: normal; color: #E47C2D; }\n.cover .ttl .form { font-weight: 300; }\n.cover .who { position: absolute; left: 54.3pt; right: 54.3pt; top: 565.1pt; height: 30pt; display: flex; align-items: center; font: 300 22pt/30pt Manrope, sans-serif; color: #fff; white-space: nowrap; }\n.cover .who span:first-child { min-width: 0; overflow: hidden; text-overflow: ellipsis; }\n.cover .who i { flex: none; width: .56em; height: .56em; border-radius: 50%; background: #fff; margin: .17em .82em 0; }\n\n/* contents */\n.toc { padding: 17pt 22pt; }\n.toc .grp + .grp { margin-top: 7pt; }\n.toc .it { display: flex; justify-content: space-between; gap: 12pt; font: 400 11.5pt/14.5pt Inter, sans-serif; color: var(--c); }\n.toc .it span:last-child { font-weight: 500; font-variant-numeric: tabular-nums; }\n.toc .it.sub { font: 300 10.5pt/13.2pt Inter, sans-serif; padding-left: 18pt; }\n.toc .it.sub span:last-child { font-weight: 300; }\n\n/* structure diagram */\n.tree { display: flex; flex-direction: column; align-items: center; gap: 12pt; }\n.chip { border-radius: 8pt; color: #fff; font: 600 8.5pt/10.5pt Manrope, sans-serif; text-align: center; padding: 6pt 6pt; background: linear-gradient(180deg, var(--l), var(--f)); }\n.tree .top { --f: #42A2DA; --l: #6FB9E4; padding: 7pt 16pt; }\n.tree .cols { display: grid; grid-template-columns: repeat(5, 1fr); gap: 8pt; width: 100%; align-items: start; }\n.tree .col { display: flex; flex-direction: column; gap: 6pt; }\n.tree .col .chip.f { font-weight: 500; opacity: .88; }\n.read { display: flex; gap: 18pt; align-items: center; }\n.read .gauge { width: 132pt; flex: none; }\n\n/* highlight lists */\n.cols3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12pt; }\n.mini { padding: 13pt 14pt; }\n.mini h5 { font: 700 9pt/12pt Manrope, sans-serif; letter-spacing: .06em; text-transform: uppercase; color: #6B7380; margin: 0 0 7pt; }\n.mini .li { display: flex; flex-wrap: wrap; gap: 0 6pt; align-items: baseline; white-space: nowrap; font: 400 10.5pt/15pt Inter, sans-serif; }\n.mini .li i { width: 6pt; height: 6pt; border-radius: 50%; flex: none; background: var(--c); transform: translateY(-1pt); }\n.mini .li span { color: #6B7380; margin-left: auto; white-space: nowrap; font-size: 9.5pt; }\n.mini .none { font: 300 10.5pt/15pt Inter, sans-serif; color: #6B7380; }\n\n/* development suggestions */\n.dev-head { display: flex; align-items: baseline; gap: 10pt; }\n.dev-head h3 { font: 500 18pt/22pt Manrope, sans-serif; color: var(--c); margin: 0; }\n.tag { font: 600 8.5pt/11pt Inter, sans-serif; color: #fff; background: var(--c); border-radius: 20pt; padding: 2.5pt 8pt; }\nh5.caps { font: 500 11pt/14pt Inter, sans-serif; text-transform: uppercase; color: var(--c); margin: 0 0 7pt; }\n\n/* action plan */\n.plan { display: grid; grid-template-columns: 1fr 1.25fr .7fr; gap: 10pt; }\n.plan .h { font: 500 13pt/16pt Manrope, sans-serif; color: #42A2DA; }\n.plan .cell { height: 186pt; border-radius: 15pt; background: #fff; box-shadow: 0 0 10pt rgba(0, 0, 0, .15); }\n\n/* coach data */\n.meta { display: flex; flex-direction: column; gap: 11pt; font: 300 11.5pt/15pt Inter, sans-serif; }\n.meta b { font-weight: 600; display: block; font-size: 9pt; color: #6B7380; text-transform: uppercase; letter-spacing: .05em; }\ntable.coach { width: 100%; border-collapse: collapse; font: 400 10.5pt/13pt Inter, sans-serif; }\ntable.coach th { font: 700 9pt/11pt Manrope, sans-serif; color: #6B7380; text-align: right; padding: 0 5pt 7pt; vertical-align: bottom; }\ntable.coach th:first-child, table.coach td:first-child { text-align: left; padding-left: 0; }\ntable.coach td { text-align: right; padding: 5pt 5pt; border-top: .5pt solid #E3E5E9; }\ntable.coach td:first-child { color: var(--c); }\ntable.coach tr.head td { font-weight: 700; border-top: 1pt solid #C9CDD3; }\ntable.coach td.you { color: #1F2733; font-weight: 600; }\ntable.coach td.oth { font-weight: 700; }\ntable.coach td.gap { color: #6B7380; }\n\n/* ---- pages that follow the 2010 report ---- */\np.tight + p.tight { margin-top: 2pt; }\np.note.mid { text-align: center; font-style: italic; }\n.stack { display: flex; flex-direction: column; align-items: center; gap: 6pt; }\n.chart + .card, .scores + .card { margin-top: 10pt; }\n/* a scale's score wheel beside its rater-group strip */\n.scores { display: flex; gap: 16pt; align-items: center; }\n.scores .wheel { width: 136pt; flex: none; }\n.scores .strip { flex: 1; min-width: 0; }\n/* one scale per page: a large wheel above the full-width strip */\n.scores.big { flex-direction: column; align-items: stretch; gap: 12pt; }\n.scores.big .wheel { width: 184pt; align-self: center; }\n.scores.big .strip { flex: none; }\n.page.tight .scores.big { gap: 8pt; }\n.page.tight .scores.big .wheel { width: 150pt; }\n.list2 { display: grid; grid-template-columns: 1fr 1fr; gap: 0 20pt; padding: 12pt 15pt; }\n.list2 li + li { margin-top: 3pt; }\n\n/* what the TEIQue measures: factor, its facets, one line each */\n.fmap { display: flex; flex-direction: column; gap: 12pt; }\n.fmap .grp { display: grid; grid-template-columns: 104pt 1fr; gap: 10pt; align-items: center; }\n.fmap .grp > .chip { padding: 10pt 6pt; font-size: 10.5pt; line-height: 12.5pt; }\n.fmap .rows { display: flex; flex-direction: column; gap: 5pt; }\n.fmap .r { display: grid; grid-template-columns: 122pt 1fr; gap: 10pt; align-items: center; }\n.fmap .chip.f { font-weight: 600; font-size: 9.5pt; line-height: 11.5pt; color: #1F2733; background: color-mix(in srgb, var(--l) 38%, #fff); }\n.fmap .r span { font: italic 300 10.5pt/13pt Inter, sans-serif; }\n\n/* report contents list */\n.items { display: flex; flex-direction: column; gap: 8pt; }\n.items .card { padding: 10pt 15pt; }\n.items h5 { font: 500 12pt/15pt Inter, sans-serif; color: var(--c); margin: 0 0 3pt; }\n.items p { font-size: 11pt; line-height: 14pt; }\n\n/* rater groups */\n.rg + .rg { margin-top: 14pt; }\n.rg h5 { font: 500 12.5pt/16pt Inter, sans-serif; color: var(--c); margin: 0 0 4pt; }\n.rl { display: grid; grid-template-columns: 140pt 1fr; gap: 10pt; font: 300 11.5pt/17.5pt Inter, sans-serif; }\n\n/* low scorers / high scorers */\n.scorers { display: grid; grid-template-columns: 1fr 1fr; gap: 14pt; align-items: stretch; }\n.scorers .card { padding: 14pt 15pt; background: color-mix(in srgb, var(--c) 9%, #fff); }\n.scorers p { font-size: 12pt; line-height: 15.5pt; text-align: left; hyphens: manual; }\n.scorers b { color: var(--c); }\n.scorers b, .dev b { font-weight: 600; }\n.dev-head { margin-bottom: 10pt; }\n\n/* acknowledgement */\n.ack h5 { font: 600 11pt/14.5pt Inter, sans-serif; margin: 0 0 4pt; }\n.ack p { font-size: 11pt; line-height: 14.5pt; text-align: left; }\n.ack p + h5 { margin-top: 14pt; }\n\n/* coach data */\np.valid { font: 400 11pt/14pt Inter, sans-serif; text-align: center; background: #F2F3F5; border-radius: 8pt; padding: 6pt; }\n.coachrow { display: grid; grid-template-columns: 1fr 170pt; gap: 14pt; align-items: start; }\ntable.coach tr.sep th { padding-top: 14pt; }\n","ffCss":"/* TEIQue Full Form report: what its pages add to the 360's page styles (teique-360/src/report/report.css).\n   Units are points, as in the Figma frames (595 x 842). */\nh1.title i, .hdr .prod i { font-style: normal; color: #E47C2D; }\nh4.sub.blue { color: #42A2DA; margin: 0; }\nh1.title.second { margin-top: 6pt; }\n\n/* headings inside an interpretation card (Leadership: \"Possible Positive\", \"Possible Negative\") */\n.card h5.ch { font: 600 12pt/14.5pt Inter, sans-serif; margin: 0 0 6pt; }\n.card p + .ch-group, .card .ch-group + p, .card .ch-group + .ch-group { margin-top: 12pt; }\n\n/* scale pages: definition beside the score wheel (Figma 238:1542, 238:1578) */\n.row .txt p.lead { margin: 0 0 10pt; }\n.row .gauge { width: 150pt; margin-top: -4pt; }\n\n/* a scale page whose text would not fit tries slightly smaller type before the card moves on to a new page */\n.page.tight .body { gap: 12pt; }\n.page.tight .row .txt p, .page.tight .card p { font-size: 11pt; line-height: 13.4pt; }\n.page.tight .card h5.ch { font-size: 11pt; line-height: 13.4pt; }\n.page.tight .row .gauge { width: 132pt; }\n\n/* structure page: the score explanation card with the three example wheels */\n.scores-card .lead-row { display: flex; gap: 12pt; align-items: center; margin-bottom: 8pt; }\n.scores-card .lead-row p { flex: 1; min-width: 0; }\n.examples { display: flex; gap: 4pt; flex: none; }\n.examples .ex { width: 62pt; display: flex; flex-direction: column; align-items: center; font: 300 7.5pt/9pt Inter, sans-serif; color: #808080; }\n.examples svg { width: 62pt; height: auto; display: block; }\n\n/* uses page */\n.chart.bubbles { width: 470pt; align-self: center; margin-top: 18pt; }\n\n/* wheel page */\n.chart.wheel-chart { width: 450pt; align-self: center; }\n.quote { margin: 0; text-align: center; }\n.quote blockquote { margin: 0; font: italic 300 12pt/16pt Inter, sans-serif; }\n.quote figcaption { margin-top: 8pt; font: 500 11pt/14pt Inter, sans-serif; }\n"};
